import { afterEach, describe, expect, it, vi } from "vitest";
import { createSafeErrorDiagnostic } from "./error-policy.js";
import { AsyncTtlCache } from "./cache.js";

describe("AsyncTtlCache", () => {
	afterEach(() => {
		vi.useRealTimers();
	});

	it("returns cached values for subsequent hits before TTL expiry", async () => {
		const cache = new AsyncTtlCache<string, string>({
			ttlMs: 60_000,
			maxSize: 2,
		});
		const fetcher = vi.fn().mockResolvedValue("bench");

		const first = await cache.getOrFetch("catalog", fetcher);
		const second = await cache.getOrFetch("catalog", fetcher);

		expect(first).toBe("bench");
		expect(second).toBe("bench");
		expect(fetcher).toHaveBeenCalledTimes(1);
	});

	it("expires entries after TTL and fetches again", async () => {
		vi.useFakeTimers();
		vi.setSystemTime(new Date("2026-01-01T00:00:00.000Z"));

		const cache = new AsyncTtlCache<string, string>({
			ttlMs: 1_000,
			maxSize: 2,
		});
		const fetcher = vi
			.fn()
			.mockResolvedValueOnce("first")
			.mockResolvedValueOnce("second");

		await cache.getOrFetch("catalog", fetcher);
		vi.advanceTimersByTime(1_001);
		const refreshed = await cache.getOrFetch("catalog", fetcher);

		expect(refreshed).toBe("second");
		expect(fetcher).toHaveBeenCalledTimes(2);
	});

	it("evicts the least recently used entry when max size is exceeded", async () => {
		const cache = new AsyncTtlCache<string, string>({
			ttlMs: 60_000,
			maxSize: 2,
		});

		const fetcher = vi.fn((key: string) => Promise.resolve(`${key}-value`));
		const load = (key: string) => cache.getOrFetch(key, () => fetcher(key));

		await load("a");
		await load("b");
		await load("a");
		await load("c");
		await load("b");

		expect(fetcher.mock.calls.map(([key]) => key)).toEqual([
			"a",
			"b",
			"c",
			"b",
		]);
	});

	it("supports refresh bypass while preserving newly fetched value", async () => {
		const cache = new AsyncTtlCache<string, string>({
			ttlMs: 60_000,
			maxSize: 2,
		});
		const fetcher = vi
			.fn()
			.mockResolvedValueOnce("stale")
			.mockResolvedValueOnce("fresh");

		await cache.getOrFetch("catalog", fetcher);
		const refreshed = await cache.getOrFetch("catalog", fetcher, {
			refresh: true,
		});
		const cached = await cache.getOrFetch("catalog", fetcher);

		expect(refreshed).toBe("fresh");
		expect(cached).toBe("fresh");
		expect(fetcher).toHaveBeenCalledTimes(2);
	});

	it("de-duplicates concurrent in-flight fetches for the same key", async () => {
		const cache = new AsyncTtlCache<string, string>({
			ttlMs: 60_000,
			maxSize: 2,
		});

		let resolveFetch: ((value: string) => void) | undefined;
		const fetcher = vi.fn(
			() =>
				new Promise<string>((resolve) => {
					resolveFetch = resolve;
				}),
		);

		const first = cache.getOrFetch("catalog", fetcher);
		const second = cache.getOrFetch("catalog", fetcher);

		expect(fetcher).toHaveBeenCalledTimes(1);

		if (!resolveFetch) {
			throw new Error("Expected fetch resolver to be assigned.");
		}
		resolveFetch("shared");

		const [firstResult, secondResult] = await Promise.all([first, second]);
		expect(firstResult).toBe("shared");
		expect(secondResult).toBe("shared");
	});

	it("does not poison cache after failed fetch and retries on next call", async () => {
		const cache = new AsyncTtlCache<string, string>({
			ttlMs: 60_000,
			maxSize: 2,
		});

		const fetcher = vi
			.fn()
			.mockRejectedValueOnce(new Error("catalog fetch failed"))
			.mockResolvedValueOnce("recovered");

		await expect(cache.getOrFetch("catalog", fetcher)).rejects.toThrow(
			"catalog fetch failed",
		);
		await expect(cache.getOrFetch("catalog", fetcher)).resolves.toBe(
			"recovered",
		);

		expect(fetcher).toHaveBeenCalledTimes(2);
	});

	it("does not let an older unshared fetch commit after the newer generation settles", async () => {
		const cache = new AsyncTtlCache<string, string>({
			ttlMs: 60_000,
			maxSize: 2,
		});
		let resolveFirst!: (value: string) => void;
		const fetcher = vi
			.fn()
			.mockImplementationOnce(
				() =>
					new Promise<string>((resolve) => {
						resolveFirst = resolve;
					}),
			)
			.mockResolvedValueOnce("newer");

		const first = cache.getOrFetch("catalog", fetcher, {
			shareInFlight: false,
		});
		const second = cache.getOrFetch("catalog", fetcher, {
			shareInFlight: false,
		});

		await expect(second).resolves.toBe("newer");
		resolveFirst("older");
		await expect(first).resolves.toBe("older");
		// The newer request cleaned up its generation before the older one
		// settled; the older result must still be rejected for cache commit.
		await expect(
			cache.getOrFetch("catalog", () => Promise.resolve("unused")),
		).resolves.toBe("newer");
	});

	it("keeps caller cancellation classifiable while waiting on shared work", async () => {
		const cache = new AsyncTtlCache<string, string>({
			ttlMs: 60_000,
			maxSize: 2,
		});
		let resolveFetch!: (value: string) => void;
		const first = cache.getOrFetch(
			"catalog",
			() =>
				new Promise<string>((resolve) => {
					resolveFetch = resolve;
				}),
		);
		const controller = new AbortController();
		const second = cache.getOrFetch(
			"catalog",
			() => Promise.resolve("shared"),
			{
				signal: controller.signal,
			},
		);
		controller.abort(new DOMException("caller cancelled", "AbortError"));
		const error = await second.catch((reason: Error | string) => reason);
		expect(createSafeErrorDiagnostic(error)).toMatchObject({
			outcome: "cancelled",
			commit_state: "unknown",
			safe_to_retry: false,
		});
		resolveFetch("shared");
		await first;
	});

	it("rejects an already-canceled caller before returning a cached value", async () => {
		const cache = new AsyncTtlCache<string, string>({
			ttlMs: 60_000,
			maxSize: 2,
		});
		await cache.getOrFetch("catalog", () => Promise.resolve("cached"));
		const controller = new AbortController();
		const reason = new DOMException("caller canceled", "AbortError");
		controller.abort(reason);

		await expect(
			cache.getOrFetch("catalog", () => Promise.resolve("unused"), {
				signal: controller.signal,
			}),
		).rejects.toBe(reason);
	});

	it("rejects a caller whose cache deadline has already elapsed", async () => {
		const cache = new AsyncTtlCache<string, string>({
			ttlMs: 60_000,
			maxSize: 2,
		});
		await cache.getOrFetch("catalog", () => Promise.resolve("cached"));

		await expect(
			cache.getOrFetch("catalog", () => Promise.resolve("unused"), {
				deadline: Date.now() - 1,
			}),
		).rejects.toMatchObject({ name: "TimeoutError" });
	});

	it("enforces a caller deadline while shared work is still pending", async () => {
		vi.useFakeTimers();
		const cache = new AsyncTtlCache<string, string>({
			ttlMs: 60_000,
			maxSize: 2,
		});
		const pending = cache.getOrFetch(
			"catalog",
			() => new Promise<string>(() => {}),
		);
		const request = cache.getOrFetch(
			"catalog",
			() => Promise.resolve("unused"),
			{ deadline: Date.now() + 1_000 },
		);
		const rejected = expect(request).rejects.toMatchObject({
			name: "TimeoutError",
		});

		await vi.advanceTimersByTimeAsync(1_000);
		await rejected;
		void pending;
	});

	it("observes cache states without exposing keys", async () => {
		const events: string[] = [];
		const cache = new AsyncTtlCache<string, string>({
			ttlMs: 60_000,
			maxSize: 2,
			observer: {
				start: ({ state }) => {
					events.push(`start:${state}`);
					return { finish: () => events.push(`finish:${state}`) };
				},
			},
		});
		let resolveFetch!: (value: string) => void;
		const fetcher = vi
			.fn()
			.mockImplementationOnce(
				() =>
					new Promise<string>((resolve) => {
						resolveFetch = resolve;
					}),
			)
			.mockResolvedValueOnce("fresh");

		const first = cache.getOrFetch("private-key", fetcher);
		const second = cache.getOrFetch("private-key", fetcher);
		expect(events).toEqual(["start:miss", "start:inflight_wait"]);

		resolveFetch("catalog");
		await Promise.all([first, second]);
		await cache.getOrFetch("private-key", fetcher);
		await cache.getOrFetch("private-key", fetcher, { refresh: true });

		expect(events).toEqual([
			"start:miss",
			"start:inflight_wait",
			"finish:miss",
			"finish:inflight_wait",
			"start:hit",
			"finish:hit",
			"start:refresh",
			"finish:refresh",
		]);
		expect(JSON.stringify(events)).not.toContain("private-key");
	});
});

import { describe, expect, it, vi } from "vitest";
import { createHevyClient, type HevyClient } from "@hevy-mcp/hevy-client";
import { createExerciseTemplateCatalog } from "./exercise-template-catalog.js";

describe("exercise template catalog", () => {
	it("reset clears the lifecycle cache and forces a fresh catalog request", async () => {
		const fetchMock = vi
			.fn()
			.mockResolvedValueOnce(
				new Response(
					JSON.stringify({
						page: 1,
						page_count: 1,
						exercise_templates: [{ id: "first", title: "First" }],
					}),
					{ headers: { "content-type": "application/json" } },
				),
			)
			.mockResolvedValueOnce(
				new Response(
					JSON.stringify({
						page: 1,
						page_count: 1,
						exercise_templates: [{ id: "second", title: "Second" }],
					}),
					{ headers: { "content-type": "application/json" } },
				),
			);
		const client = createHevyClient({ apiKey: "key", fetch: fetchMock });
		const catalog = createExerciseTemplateCatalog(client);

		await expect(catalog.get()).resolves.toMatchObject([{ id: "first" }]);
		await expect(catalog.get()).resolves.toMatchObject([{ id: "first" }]);
		catalog.reset();
		await expect(catalog.get()).resolves.toMatchObject([{ id: "second" }]);
		expect(fetchMock).toHaveBeenCalledTimes(2);
	});
	it("deduplicates concurrent cache misses", async () => {
		let resolveResponse!: (response: Response) => void;
		const pendingResponse = new Promise<Response>((resolve) => {
			resolveResponse = resolve;
		});
		const fetchMock = vi.fn().mockReturnValue(pendingResponse);
		const client = createHevyClient({ apiKey: "key", fetch: fetchMock });
		const catalog = createExerciseTemplateCatalog(client);

		const first = catalog.get();
		const second = catalog.get();
		expect(fetchMock).toHaveBeenCalledOnce();
		resolveResponse(
			new Response(
				JSON.stringify({
					page: 1,
					page_count: 1,
					exercise_templates: [{ id: "shared", title: "Shared" }],
				}),
				{ headers: { "content-type": "application/json" } },
			),
		);

		await expect(Promise.all([first, second])).resolves.toEqual([
			[{ id: "shared", title: "Shared" }],
			[{ id: "shared", title: "Shared" }],
		]);
	});

	it("does not share a controlled refresh between independently cancellable callers", async () => {
		const firstController = new AbortController();
		const secondController = new AbortController();
		type ExerciseTemplatesResponse = Awaited<
			ReturnType<HevyClient["getExerciseTemplates"]>
		>;
		const responses: Array<Promise<ExerciseTemplatesResponse>> = [
			new Promise<ExerciseTemplatesResponse>((resolve, reject) => {
				firstController.signal.addEventListener(
					"abort",
					() => reject(firstController.signal.reason),
					{ once: true },
				);
				setTimeout(
					() =>
						resolve({
							page: 1,
							page_count: 1,
							exercise_templates: [{ id: "first", title: "First" }],
						}),
					100,
				);
			}),
			new Promise<ExerciseTemplatesResponse>((resolve) =>
				setTimeout(
					() =>
						resolve({
							page: 1,
							page_count: 1,
							exercise_templates: [{ id: "second", title: "Second" }],
						}),
					20,
				),
			),
		];
		const getExerciseTemplates = vi.fn<HevyClient["getExerciseTemplates"]>(
			(_params, _options) => {
				const response = responses.shift();
				if (!response) throw new Error("Unexpected extra page");
				return response;
			},
		);
		const client = {
			getExerciseTemplates,
		} satisfies Pick<HevyClient, "getExerciseTemplates">;
		const catalog = createExerciseTemplateCatalog(client);

		const first = catalog.get({
			execution: { signal: firstController.signal },
		});
		const second = catalog.get({
			execution: { signal: secondController.signal },
		});
		firstController.abort(new DOMException("first canceled", "AbortError"));

		await expect(first).rejects.toMatchObject({ name: "AbortError" });
		await expect(second).resolves.toMatchObject([{ id: "second" }]);
		expect(getExerciseTemplates).toHaveBeenCalledTimes(2);
	});

	it("returns an empty catalog when a page omits its template array", async () => {
		const fetchMock = vi.fn().mockResolvedValue(
			new Response(JSON.stringify({ page: 1, page_count: 1 }), {
				headers: { "content-type": "application/json" },
			}),
		);
		const client = createHevyClient({ apiKey: "key", fetch: fetchMock });
		const catalog = createExerciseTemplateCatalog(client);

		await expect(catalog.get()).resolves.toEqual([]);
		expect(fetchMock).toHaveBeenCalledOnce();
	});
});

import { describe, expect, it, vi } from "vitest";
import { Context, Effect, Layer, Option } from "effect";
import {
	ExerciseTemplateCatalogService,
	HevyClientService,
	HevyOperationsService,
	ToolExecutionContextService,
	ToolObserverService,
} from "../effect-services.js";
import { createMockHevyClient } from "../../test-fixtures/mock-hevy.js";
import {
	createToolRuntime,
	HEVY_CLIENT_NOT_INITIALIZED_ERROR,
} from "./tool-runtime.js";
import { createOperations } from "@hevy-mcp/operations";

const runImmediately = <T>(operation: () => Promise<T>): Promise<T> =>
	operation();

const catalog = {
	get: () => Promise.resolve([]),
	reset: () => undefined,
};

function resolveRuntimeServices(runtime: ReturnType<typeof createToolRuntime>) {
	if (!runtime.layer) {
		throw new Error("Expected runtime to provide a service layer");
	}
	return Effect.runSync(Effect.scoped(Layer.build(runtime.layer)));
}

describe("createToolRuntime service layer", () => {
	it("throws the canonical not-initialized error for client service lookup without a client", () => {
		const runtime = createToolRuntime({
			client: null,
			operations: createOperations(createMockHevyClient()),
			catalog,
		});

		expect(() => runtime.service(HevyClientService)).toThrowError(
			HEVY_CLIENT_NOT_INITIALIZED_ERROR,
		);
		expect(() => runtime.getClient()).toThrowError(
			HEVY_CLIENT_NOT_INITIALIZED_ERROR,
		);
	});

	it("provides core services from the objects passed to the runtime", () => {
		const client = createMockHevyClient();
		const operations = createOperations(client);
		const execution = {
			requestId: "request-1",
			deadline: 123,
		};
		const runtime = createToolRuntime({
			client,
			operations,
			catalog,
			execution,
		});
		const services = resolveRuntimeServices(runtime);

		expect(Context.get(services, HevyClientService)).toBe(runtime.getClient());
		expect(Context.get(services, HevyOperationsService)).toBe(operations);
		expect(Context.get(services, ExerciseTemplateCatalogService)).toBe(
			runtime.catalog,
		);
		expect(Context.get(services, ToolExecutionContextService)).toBe(execution);
		expect(runtime.getClient()).toBe(Context.get(services, HevyClientService));
		expect(runtime.service(HevyClientService)).toBe(runtime.getClient());
		expect(runtime.getOperations()).toBe(
			Context.get(services, HevyOperationsService),
		);
		expect(runtime.service(HevyOperationsService)).toBe(
			runtime.getOperations(),
		);
	});

	it("composes the observer service only when an observer is configured", () => {
		const withObserver = { start: vi.fn() };
		const observedRuntime = createToolRuntime({
			client: createMockHevyClient(),
			catalog,
			observer: withObserver,
		});
		const observedServices = resolveRuntimeServices(observedRuntime);
		expect(Context.get(observedServices, ToolObserverService)).toBe(
			withObserver,
		);

		const unobservedRuntime = createToolRuntime({
			client: createMockHevyClient(),
			catalog,
		});
		const unobservedServices = resolveRuntimeServices(unobservedRuntime);
		expect(Context.getOption(unobservedServices, ToolObserverService)).toBe(
			Option.none(),
		);
	});

	it("rebinds execution-scoped client, catalog, and context without rebinding operations", () => {
		const client = createMockHevyClient();
		const operations = createOperations(client);
		const runtime = createToolRuntime({
			client,
			operations,
			catalog,
		});
		const signal = new AbortController().signal;
		const scoped = runtime.forExecution({ signal, deadline: 456 });
		const parentServices = resolveRuntimeServices(runtime);
		const scopedServices = resolveRuntimeServices(scoped);

		expect(Context.get(parentServices, HevyClientService)).toBe(client);
		expect(Context.get(scopedServices, HevyClientService)).toBe(
			scoped.getClient(),
		);
		expect(Context.get(scopedServices, HevyClientService)).not.toBe(client);
		expect(Context.get(scopedServices, ExerciseTemplateCatalogService)).toBe(
			scoped.catalog,
		);
		expect(scoped.catalog).not.toBe(catalog);
		expect(Context.get(scopedServices, ToolExecutionContextService)).toBe(
			scoped.execution,
		);
		expect(Context.get(scopedServices, HevyOperationsService)).toBe(operations);
		expect(Context.get(parentServices, ExerciseTemplateCatalogService)).toBe(
			catalog,
		);
		expect(Context.get(parentServices, HevyOperationsService)).toBe(operations);
	});
});

describe("createToolRuntime observation scope", () => {
	it("does not execute a write handler twice when run instrumentation fails", async () => {
		let executions = 0;
		const finish = vi.fn();
		const runtime = createToolRuntime({
			client: null,
			catalog,
			observer: {
				start: () => ({
					run: () => {
						throw new Error("instrumentation failed");
					},
					finish,
				}),
			},
		});
		const handler = runtime.createHandler(() => {
			executions += 1;
			return Promise.resolve({ content: [{ type: "text", text: "ok" }] });
		}, "create-workout");

		await expect(handler({ id: "workout-id" })).resolves.toMatchObject({
			content: [{ text: "ok" }],
		});
		expect(executions).toBe(1);
		expect(finish).toHaveBeenCalledOnce();
	});

	it("starts the handler lazily inside the active observer scope", async () => {
		let active = false;
		const handler = vi.fn(() => {
			expect(active).toBe(true);
			return Promise.resolve({
				content: [{ type: "text" as const, text: "ok" }],
			});
		});
		let runCalls = 0;
		const run = async <T>(operation: () => Promise<T>): Promise<T> => {
			runCalls += 1;
			active = true;
			try {
				return await operation();
			} finally {
				active = false;
			}
		};
		const runtime = createToolRuntime({
			client: null,
			catalog,
			observer: { start: () => ({ run, finish: vi.fn() }) },
		});
		await runtime.createHandler(handler, "get-workout")({ workout_id: "id" });

		expect(runCalls).toBe(1);
		expect(handler).toHaveBeenCalledOnce();
	});

	it("reuses the handler result when run fails after invoking it", async () => {
		const handler = vi
			.fn()
			.mockResolvedValue({ content: [{ type: "text", text: "ok" }] });
		const runtime = createToolRuntime({
			client: null,
			catalog,
			observer: {
				start: () => ({
					run: async (operation) => {
						await operation();
						throw new Error("observer failed after execution");
					},
					finish: vi.fn(),
				}),
			},
		});

		await expect(
			runtime.createHandler(handler, "create-workout")({}),
		).resolves.toMatchObject({ content: [{ text: "ok" }] });
		expect(handler).toHaveBeenCalledOnce();
	});

	it("emits only allowlisted taxonomy and bounded argument structure", async () => {
		const start = vi.fn(() => ({
			run: runImmediately,
			finish: vi.fn(),
		}));
		const runtime = createToolRuntime({
			client: null,
			catalog,
			observer: { start },
		});
		const secret = "private-routine-title-sentinel";
		const handler = runtime.createHandler(
			() => Promise.resolve({ content: [] }),
			"list-routines",
			{ feature: "routines", kind: "read", operation: "list" },
		);

		await handler({
			page: 12,
			page_size: 5,
			query: secret,
			workout_id: "private-workout-id",
			include_custom: true,
			private_note: secret,
		});

		expect(start).toHaveBeenCalledWith({
			name: "list-routines",
			taxonomy: { feature: "routines", kind: "read", operation: "list" },
			argumentKeys: [
				"page",
				"page_size",
				"workout_id",
				"include_custom",
				"query",
			],
			argumentPresence: { workout_id: true, query: true },
			numericArgumentBuckets: { page: "11-50", page_size: "2-10" },
			booleanArguments: { include_custom: true },
			argumentKeyCountBucket: "2-10",
		});
		expect(JSON.stringify(start.mock.calls)).not.toContain(secret);
		expect(JSON.stringify(start.mock.calls)).not.toContain(
			"private-workout-id",
		);
		expect(JSON.stringify(start.mock.calls)).not.toContain("privateNote");
	});

	it("reports bounded result content counts", async () => {
		const finish = vi.fn();
		const runtime = createToolRuntime({
			client: null,
			catalog,
			observer: {
				start: () => ({
					run: (operation) => operation(),
					finish,
				}),
			},
		});
		const content = Array.from({ length: 12 }, (_, index) => ({
			type: "text" as const,
			text: `result-${index}`,
		}));

		await runtime.createHandler(
			() => Promise.resolve({ content }),
			"list-workouts",
		)({});

		expect(finish).toHaveBeenCalledWith(
			expect.objectContaining({
				result: expect.objectContaining({ contentCountBucket: "11-50" }),
			}),
		);
		expect(JSON.stringify(finish.mock.calls)).not.toContain(
			'"contentCount":12',
		);
	});

	it("reports a safe thrown-error diagnostic without exception text", async () => {
		const finish = vi.fn();
		const secret = "private-handler-error-sentinel";
		const runtime = createToolRuntime({
			client: null,
			catalog,
			observer: {
				start: () => ({
					run: (operation) => operation(),
					finish,
				}),
			},
		});
		const stderr = vi.spyOn(console, "error").mockImplementation(() => {});

		const result = await runtime.createHandler(
			() => Promise.reject(new Error(secret)),
			"get-workouts",
		)({});

		expect(result).toMatchObject({ isError: true });
		expect(finish).toHaveBeenCalledWith(
			expect.objectContaining({
				outcome: "thrown_error",
				errorType: "UNKNOWN_ERROR",
				error: expect.objectContaining({ category: "Error" }),
			}),
		);
		expect(JSON.stringify(finish.mock.calls)).not.toContain(secret);
		stderr.mockRestore();
	});

	it("lets the newest nested execution scope control the client", async () => {
		const client = createMockHevyClient();
		const getUserInfo = client.getUserInfo.mockResolvedValue({
			data: { id: "user" },
		});
		const runtime = createToolRuntime({ client, catalog });
		const firstSignal = new AbortController().signal;
		const secondSignal = new AbortController().signal;
		const first = runtime.forExecution({
			signal: firstSignal,
			deadline: 111,
		});
		const second = first.forExecution({
			signal: secondSignal,
			deadline: 222,
		});

		expect(second.executionDeadline).toBe(222);
		await second.getClient().getUserInfo();

		expect(getUserInfo).toHaveBeenCalledWith({
			signal: secondSignal,
			deadline: 222,
		});
	});

	it("cleans up fallback listeners across repeated execution scopes", () => {
		const nativeDescriptor = Object.getOwnPropertyDescriptor(
			AbortSignal,
			"any",
		);
		Object.defineProperty(AbortSignal, "any", {
			value: undefined,
			configurable: true,
		});
		try {
			const lifecycle = new AbortController();
			const removeEventListener = vi.spyOn(
				lifecycle.signal,
				"removeEventListener",
			);
			const runtime = createToolRuntime({
				client: null,
				catalog,
				lifecycleSignal: lifecycle.signal,
			});

			for (let index = 0; index < 3; index += 1) {
				const request = new AbortController();
				const scoped = runtime.forExecution({ signal: request.signal });
				request.abort();
				expect(scoped.execution?.signal?.aborted).toBe(true);
			}

			expect(removeEventListener).toHaveBeenCalledTimes(3);
		} finally {
			if (nativeDescriptor) {
				Object.defineProperty(AbortSignal, "any", nativeDescriptor);
			} else {
				Reflect.deleteProperty(AbortSignal, "any");
			}
		}
	});
});

