{
	"extends": "../../tsconfig.base.json",
	"compilerOptions": {
		"lib": ["ESNext", "DOM", "DOM.Iterable"],
		"types": []
	},
	"include": ["src/**/*.ts"],
	"exclude": ["src/**/*.test.ts"]
}

import { fileURLToPath } from "node:url";
import { configDefaults, defineConfig } from "vitest/config";

export default defineConfig({
	resolve: {
		alias: {
			// @cloudflare/workers-oauth-provider imports this Workers runtime
			// module; outside workerd it needs a shim.
			"cloudflare:workers": fileURLToPath(
				new URL("./tests/shims/cloudflare-workers.ts", import.meta.url).href,
			),
		},
	},
	test: {
		setupFiles: [
			fileURLToPath(
				new URL("./tests/setup/cloudflare-runtime.ts", import.meta.url).href,
			),
		],
		server: {
			deps: {
				// Inline so the `cloudflare:workers` alias above applies to the
				// library's own import of that runtime-only module.
				inline: ["@cloudflare/workers-oauth-provider"],
			},
		},
		exclude: [
			...configDefaults.exclude,
			"tests/nightly/**",
			"tests/cloudflare/**",
		],
		coverage: {
			provider: "v8",
			reportsDirectory: "coverage",
			reporter: ["text", "lcov"],
			exclude: ["tests/performance/**"],
		},
	},
});

import { spawnSync } from "node:child_process";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const vitest = resolve(root, "node_modules/vitest/vitest.mjs");
const [lane, ...forwardedArgs] = process.argv.slice(2);
const selectors = {
	unit: [
		"--exclude",
		"tests/integration/**",
		"--exclude",
		"tests/performance/**",
	],
	mocked: ["tests/integration/mocked"],
};
if (!Object.hasOwn(selectors, lane)) {
	throw new Error(`Unknown Vitest lane ${lane || "<missing>"}`);
}

const args = ["run", ...selectors[lane]];
if (lane === "unit") {
	// Lets slow, expensive tests that duplicate the `check` targets skip
	// themselves in the fast unit lane (see check-generated-client.test.ts).
	process.env.HEVY_UNIT_LANE = "1";
}
if (process.env.HEVY_TEST_REPORT_MODE === "ci") {
	const nodeMajor = Number.parseInt(process.versions.node, 10);
	if (lane === "unit") {
		args.push("--coverage", "--coverage.reportsDirectory=coverage/unit");
		if (nodeMajor === 24) {
			args.push(
				"--reporter=default",
				"--reporter=junit",
				"--outputFile.junit=test-results/unit-tests.xml",
			);
		}
	}
	if (lane === "mocked" && nodeMajor === 24) {
		args.push("--coverage", "--coverage.reportsDirectory=coverage/mocked");
	}
}
args.push(...forwardedArgs);

const result = spawnSync(process.execPath, [vitest, ...args], {
	cwd: root,
	env: process.env,
	stdio: "inherit",
});
if (result.error) throw result.error;
if (result.status !== 0) {
	throw new Error(
		`Vitest ${lane} lane failed with ${result.signal ? `signal ${result.signal}` : `exit code ${result.status ?? 1}`}`,
	);
}

import type { McpServer } from "@modelcontextprotocol/server";
import { McpServer as Server } from "@modelcontextprotocol/server";
import { createHevyClient, type HevyClient } from "@hevy-mcp/hevy-client";
import type {
	GetV1RoutinesQuery,
	GetV1WorkoutsQuery,
} from "@hevy-mcp/hevy-client/types";
import { vi } from "vitest";

export function createMockHevyClient() {
	const methods = {
		getWorkouts: vi.fn(),
		getWorkout: vi.fn(),
		createWorkout: vi.fn(),
		updateWorkout: vi.fn(),
		getWorkoutCount: vi.fn(),
		getWorkoutEvents: vi.fn(),
		getRoutines: vi.fn(),
		getRoutineById: vi.fn(),
		createRoutine: vi.fn(),
		updateRoutine: vi.fn(),
		getExerciseTemplates: vi.fn(),
		getExerciseTemplate: vi.fn(),
		getExerciseHistory: vi.fn(),
		createExerciseTemplate: vi.fn(),
		getRoutineFolders: vi.fn(),
		createRoutineFolder: vi.fn(),
		getRoutineFolder: vi.fn(),
		getBodyMeasurements: vi.fn(),
		getBodyMeasurement: vi.fn(),
		createBodyMeasurement: vi.fn(),
		updateBodyMeasurement: vi.fn(),
		getUserInfo: vi.fn(),
	} satisfies HevyClient;

	const client = createHevyClient({
		apiKey: "test-key",
		maxGetRetries: 0,
		fetch: async (input) => {
			const url = input instanceof Request ? input.url : String(input);
			const parsedUrl = new URL(url);
			switch (parsedUrl.pathname) {
				case "/v1/workouts": {
					const query =
						parsedUrl.search.length === 0
							? undefined
							: ({
									page: Number(parsedUrl.searchParams.get("page")),
									pageSize: Number(parsedUrl.searchParams.get("pageSize")),
								} satisfies GetV1WorkoutsQuery);
					const data =
						query === undefined
							? await methods.getWorkouts()
							: await methods.getWorkouts(query);
					return new Response(JSON.stringify(data ?? {}), {
						status: 200,
						headers: { "content-type": "application/json" },
					});
				}
				default:
					break;
			}
			if (parsedUrl.pathname.startsWith("/v1/workouts/")) {
				const workoutId = decodeURIComponent(
					parsedUrl.pathname.slice("/v1/workouts/".length),
				);
				const data = await methods.getWorkout(workoutId);
				return new Response(JSON.stringify(data ?? {}), {
					status: 200,
					headers: { "content-type": "application/json" },
				});
			}
			if (parsedUrl.pathname.startsWith("/v1/routines/")) {
				const routineId = decodeURIComponent(
					parsedUrl.pathname.slice("/v1/routines/".length),
				);
				const data = await methods.getRoutineById(routineId);
				return new Response(JSON.stringify(data ?? {}), {
					status: 200,
					headers: { "content-type": "application/json" },
				});
			}
			switch (parsedUrl.pathname) {
				case "/v1/routines": {
					const query =
						parsedUrl.search.length === 0
							? undefined
							: ({
									page: Number(parsedUrl.searchParams.get("page")),
									pageSize: Number(parsedUrl.searchParams.get("pageSize")),
								} satisfies GetV1RoutinesQuery);
					const data =
						query === undefined
							? await methods.getRoutines()
							: await methods.getRoutines(query);
					return new Response(JSON.stringify(data ?? {}), {
						status: 200,
						headers: { "content-type": "application/json" },
					});
				}
				default:
					return new Response("{}", { status: 404 });
			}
		},
	});
	Object.assign(client, methods);
	return client as HevyClient & typeof methods;
}

export function createMockMcpServer() {
	const server = new Server({ name: "test-server", version: "0.0.0" });
	const registerTool = vi.spyOn(server, "registerTool");
	const registerResource = vi.spyOn(server, "registerResource");
	return { server, registerResource, registerTool } satisfies {
		server: McpServer;
		registerResource: typeof registerResource;
		registerTool: typeof registerTool;
	};
}

export const RESULT_COUNT_BUCKETS = ["0", "1", "2-10", "11-50", "51+"] as const;

export type ResultCountBucket = (typeof RESULT_COUNT_BUCKETS)[number];

export interface WorkflowResultTelemetry {
	readonly name: "training-summary" | "routine-discovery";
	readonly pagination: Readonly<Record<string, number>>;
	readonly cacheStatus: "hit" | "miss" | "not-used";
	readonly itemsScanned: number;
}

export interface ToolResultTelemetry {
	readonly itemCountBucket?: ResultCountBucket;
	readonly exerciseCountBucket?: ResultCountBucket;
	readonly setCountBucket?: ResultCountBucket;
	readonly workflow?: WorkflowResultTelemetry;
	readonly expected404Outcome?: "not_found" | "end_of_list" | "mutation_error";
}

export function bucketCount(value: number): ResultCountBucket {
	if (!Number.isFinite(value) || value <= 0) return "0";
	if (value === 1) return "1";
	if (value <= 10) return "2-10";
	if (value <= 50) return "11-50";
	return "51+";
}

type ResultOwner = { readonly content: readonly unknown[] };
const resultTelemetry = new WeakMap<ResultOwner, ToolResultTelemetry>();

export function attachResultTelemetry(
	result: ResultOwner,
	telemetry: ToolResultTelemetry | undefined,
): void {
	if (telemetry) resultTelemetry.set(result, telemetry);
}

export function getResultTelemetry(
	result: ResultOwner,
): ToolResultTelemetry | undefined {
	return resultTelemetry.get(result);
}

