					pendingLookups.push((value) => resume(Effect.succeed(value)));
				}),
		);
		const operations = {
			templates: {
				listAll: {
					descriptor: {
						id: "templates.listAll" as const,
						safety: "read" as const,
					},
					effect: listAll,
					execute: async () => [],
				},
			},
		};
