			resourcePromise,
			searchPromise,
		]);
		expect(parseJsonContent(resourceResult).data).toEqual([benchTemplate]);
		expect(JSON.parse(searchResult.content[0]?.text ?? "null")).toEqual([
			benchTemplate,
		]);
